    @Override
    public String getName() {
        return "count_action";
    }

    @Override
    public RestChannelConsumer prepareRequest(final RestRequest request, final NodeClient client) throws IOException {
        SearchRequest countRequest = createCountRequest(request);
        SearchSourceBuilder searchSourceBuilder = createCountSourceBuilder();
        countRequest.source(searchSourceBuilder);
        final int terminateAfter = request.paramAsInt("terminate_after", DEFAULT_TERMINATE_AFTER);

        applyCountQuery(request, countRequest, searchSourceBuilder);
        applyCountParameters(request, countRequest, searchSourceBuilder, terminateAfter);
        return channel -> client.search(countRequest, new RestBuilderListener<SearchResponse>(channel) {
            @Override
            public RestResponse buildResponse(SearchResponse response, XContentBuilder builder) throws Exception {
                builder.startObject();
                if (terminateAfter != DEFAULT_TERMINATE_AFTER) {
                    builder.field("terminated_early", response.isTerminatedEarly());
                }
                builder.field("count", response.getHits().getTotalHits().value());
                buildBroadcastShardsHeader(
                    builder,
                    request,
                    response.getTotalShards(),
                    response.getSuccessfulShards(),
                    0,
                    response.getFailedShards(),
                    response.getShardFailures()
                );

                builder.endObject();
                return new RestResponse(response.status(), builder);
            }
        });
    }

    private SearchRequest createCountRequest(RestRequest request) {
        SearchRequest countRequest = new SearchRequest(Strings.splitStringByCommaToArray(request.param("index")));
        IndicesOptions indicesOptions = IndicesOptions.fromRequest(request, countRequest.indicesOptions());
        if (crossProjectModeDecider.crossProjectEnabled() && countRequest.allowsCrossProject()) {
            indicesOptions = IndicesOptions.builder(indicesOptions)
                .crossProjectModeOptions(new IndicesOptions.CrossProjectModeOptions(true))
                .build();
        }
        countRequest.indicesOptions(indicesOptions);
        return countRequest;
    }

    private static SearchSourceBuilder createCountSourceBuilder() {
        return new SearchSourceBuilder().size(0).trackTotalHits(true);
    }

    private static void applyCountQuery(RestRequest request, SearchRequest countRequest, SearchSourceBuilder searchSourceBuilder)
        throws IOException {
        request.withContentOrSourceParamParserOrNull(parser -> {
            if (parser == null) {
                QueryBuilder queryBuilder = RestActions.urlParamsToQueryBuilder(request);
                if (queryBuilder != null) {
                    // since there is no request body, no need to pass in countRequest to handle project_routing param
                    searchSourceBuilder.query(queryBuilder);
                }
            } else {
                searchSourceBuilder.query(RestActions.getQueryContent(parser, countRequest));
            }
        });
    }

    private static void applyCountParameters(
        RestRequest request,
        SearchRequest countRequest,
        SearchSourceBuilder searchSourceBuilder,
        int terminateAfter
    ) {
        applyRoutingOrSliceForCountRequest(request, countRequest);

        float minScore = request.paramAsFloat("min_score", -1f);
        if (minScore != -1f) {
            searchSourceBuilder.minScore(minScore);
        }

        countRequest.preference(request.param("preference"));

        String stats = request.param("stats");
        if (stats != null) {
            searchSourceBuilder.stats(Arrays.asList(Strings.splitStringByCommaToArray(stats)));
        }

        searchSourceBuilder.terminateAfter(terminateAfter);
    }

    /**
     * Applies {@code routing} / {@code _slice} URL parameters. Matches {@link RestSearchAction#parseSearchRequest} slice handling.
     * package private for testing
     */
    static void applyRoutingOrSliceForCountRequest(RestRequest request, SearchRequest searchRequest) {
        final SliceIndexing.ParsedRouting parsedRouting = SliceIndexing.parseSearchRoutingOrSliceWithProvenance(request);
        searchRequest.routing(parsedRouting.routing());
        searchRequest.searchSlice(
            parsedRouting.fromSlice() ? (parsedRouting.routing() == null ? SliceIndexing.SLICE_ALL : parsedRouting.routing()) : null
        );
    }

}

    public List<Route> routes() {
        return List.of(new Route(GET, "/{index}/_explain/{id}"), new Route(POST, "/{index}/_explain/{id}"));
    }

    @Override
    public String getName() {
        return "explain_action";
    }

    @Override
    public RestChannelConsumer prepareRequest(final RestRequest request, final NodeClient client) throws IOException {
        validateSliceParamForExplain(request);
        ExplainRequest explainRequest = new ExplainRequest(request.param("index"), request.param("id"));
        applyRoutingAndParent(explainRequest, request);
        applyQuery(explainRequest, request);
        applyFieldParameters(explainRequest, request);
        explainRequest.fetchSourceContext(FetchSourceContext.parseFromRestRequest(request));

        return channel -> client.explain(explainRequest, new RestToXContentListener<>(channel, ExplainResponse::status));
    }

    private static void applyRoutingAndParent(ExplainRequest explainRequest, RestRequest request) {
        final SliceIndexing.ParsedRouting parsedRouting = SliceIndexing.parseRoutingOrSliceWithProvenance(request);
        explainRequest.routing(parsedRouting.routing()).setRoutingFromSlice(parsedRouting.fromSlice());
        if (explainRequest.routing() == null) {
            explainRequest.parent(request.param("parent"));
        }
        explainRequest.preference(request.param("preference"));
    }

    private static void applyQuery(ExplainRequest explainRequest, RestRequest request) throws IOException {
        String queryString = request.param("q");
        request.withContentOrSourceParamParserOrNull(parser -> {
            if (parser != null) {
                explainRequest.query(RestActions.getQueryContent(parser));
            } else if (queryString != null) {
                QueryBuilder query = RestActions.urlParamsToQueryBuilder(request);
                explainRequest.query(query);
            }
        });
    }

    private static void applyFieldParameters(ExplainRequest explainRequest, RestRequest request) {
        if (request.param("fields") != null) {
            throw new IllegalArgumentException(
                "The parameter [fields] is no longer supported, please use [stored_fields] to retrieve stored fields"
            );
        }
        String storedFields = request.param("stored_fields");
        if (storedFields != null) {
            explainRequest.storedFields(Strings.splitStringByCommaToArray(storedFields));
        }
    }

    private static void validateSliceParamForExplain(RestRequest request) {
        final String slice = request.param(SliceIndexing.PARAM_NAME);
        if (slice == null || SliceIndexing.SLICE_FEATURE_FLAG.isEnabled() == false) {
            return;
        }
        if (SliceIndexing.SLICE_ALL.equals(slice) || Strings.splitStringByCommaToArray(slice).length != 1) {
            throw new IllegalArgumentException(SINGLE_SLICE_ONLY_ERROR);
        }
    }
